      "c3",
      "c4"
    ]
  },
  "translations": [
    {
      "cueId": "c1",
      "text": "您為什麼還在外面？"
    },
    {
      "cueId": "c2",
      "text": "您打來（或叫我）時，我正打算回去。"
    },
    {
      "cueId": "c3",
      "text": "您可以稍等一下嗎？"
    },
    {
      "cueId": "c4",
      "text": "好的。"
    }
  ],
